'use strict';
const {logger}=require('../utils/logger');
const {transportFetch}=require('./proxyTransport');
class SeamlessRestError extends Error{constructor(status,code,message,details,creditsRemaining=null){super(message);this.name='SeamlessRestError';this.status=status;this.code=code;this.details=details;this.creditsRemaining=creditsRemaining}}
function numericHeader(headers,name){const raw=headers.get(name);if(raw==null||raw.trim()==='')return null;const v=Number(raw);return Number.isFinite(v)?v:null}
function classify(status,body){const code=typeof body?.code==='string'?body.code:`HTTP_${status}`;const raw=[body?.msg,body?.message,body?.error?.message,body?.error].find(v=>typeof v==='string'&&v.trim());if(code==='insufficientCredits')return{code,message:'Seamless reports insufficient Public API research credits.'};if(code==='missingLicense')return{code,message:'This Seamless connection does not have an active Public API license.'};if(status===401)return{code,message:'Seamless rejected the API key. Check the selected Render secret.'};if(status===403)return{code,message:'Seamless refused this API key. Check Public API v1 access and group permissions.'};if(status===429)return{code,message:'Seamless rate limit reached. Retry after the provider reset window.'};if(status===422&&raw)return{code,message:`Seamless rejected the request: ${String(raw).slice(0,240)}`};if(status>=500)return{code,message:`Seamless is temporarily unavailable (HTTP ${status}).`};return{code,message:raw?String(raw).slice(0,240):`Seamless request failed (HTTP ${status}).`}}
class SeamlessRestClient{
  constructor(apiKey,baseUrl='https://api.seamless.ai/api/client/v1',timeoutMs=30000,fetchImpl=null,options={}){if(!apiKey)throw new Error('Missing Seamless API key');this.apiKey=apiKey;this.baseUrl=baseUrl.replace(/\/$/,'');this.timeoutMs=timeoutMs;this.fetch=fetchImpl;this.proxyUrl=options.proxyUrl||null;this.routeId=options.routeId||'default';this.keySource=options.keySource||'SEAMLESS_API_KEY'}
  async rawRequest(url,init={}){if(this.fetch)return this.fetch(url,init);return transportFetch(url,init,this.proxyUrl)}
  async request(path,init={}){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),this.timeoutMs);try{const response=await this.rawRequest(this.baseUrl+path,{...init,headers:{Accept:'application/json',Token:this.apiKey,...(init.body?{'Content-Type':'application/json'}:{}),...(init.headers||{})},signal:controller.signal});const creditsRemaining=numericHeader(response.headers,'X-PublicAPI-Credits');const rateLimitRemaining=numericHeader(response.headers,'X-RateLimit-Remaining');const rateLimitReset=numericHeader(response.headers,'X-RateLimit-Reset');const text=await response.text();let body=null;if(text){try{body=JSON.parse(text)}catch{body={message:text.slice(0,240)}}}if(!response.ok){const c=classify(response.status,body);throw new SeamlessRestError(response.status,c.code,c.message,body?.data,creditsRemaining)}return{data:body,creditsRemaining,rateLimitRemaining,rateLimitReset,observedAt:new Date().toISOString(),routeId:this.routeId,keySource:this.keySource}}catch(error){if(error?.name==='AbortError')throw new SeamlessRestError(504,'TIMEOUT',`Seamless REST request timed out after ${this.timeoutMs}ms.`);if(!(error instanceof SeamlessRestError))logger.warn('seamless.rest.request_failed',{path,routeId:this.routeId,message:error?.message||String(error)});throw error}finally{clearTimeout(timer)}}
  searchContactsByName(fullName,limit=6){return this.request('/search/contacts',{method:'POST',body:JSON.stringify({nextToken:null,limit,fullName:[fullName]})})}
  researchSearchResult(searchResultId){return this.request('/contacts/research',{method:'POST',body:JSON.stringify({searchResultIds:[searchResultId]})})}
  researchLinkedIn(linkedinUrl){return this.request('/contacts/research',{method:'POST',body:JSON.stringify({contacts:[{liProfileUrl:linkedinUrl}],skipDeduplicationCheck:false})})}
  pollContactResearch(requestIds){return this.request(`/contacts/research/poll?${new URLSearchParams({requestIds:requestIds.join(',')})}`,{method:'GET'})}
  async getCredits(){const end=new Date();const start=new Date(end.getTime()-60_000);const iso=d=>d.toISOString().replace(/\.\d{3}Z$/,'Z');const qs=new URLSearchParams({page:'1',limit:'1',startDate:iso(start),endDate:iso(end)});const r=await this.request(`/contacts?${qs}`,{method:'GET'});return{creditsRemaining:r.creditsRemaining,rateLimitRemaining:r.rateLimitRemaining,rateLimitReset:r.rateLimitReset,observedAt:r.observedAt,routeId:this.routeId,keySource:this.keySource}}
  async getEgressIp(checkUrl='https://api.ipify.org?format=json'){
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),Math.min(this.timeoutMs,10000));try{const response=await this.rawRequest(checkUrl,{method:'GET',headers:{Accept:'application/json'},signal:controller.signal});const text=await response.text();if(!response.ok)throw new Error(`Egress check failed with HTTP ${response.status}.`);let ip='';try{const body=JSON.parse(text);ip=String(body.ip||'').trim()}catch{ip=text.trim()}if(!ip)throw new Error('Egress check returned no IP address.');return{ip,observedAt:new Date().toISOString(),routeId:this.routeId}}finally{clearTimeout(timer)}}
}
module.exports={SeamlessRestClient,SeamlessRestError};
